"""PL-01 step 3: put every ticker on one calendar."""

from __future__ import annotations

from collections.abc import Sequence

from mdata.types import GapError, Prices, RawRow


def align_calendar(rows: Sequence[RawRow], *, max_gap: int = 5) -> Prices:
    """One calendar from the first date every ticker has a close; gaps take the previous close.

    The calendar is every date any ticker has a close on, from the first date on which every
    ticker has one. Raises GapError naming the ticker when more than `max_gap` calendar dates
    in a row are missing (DATA-03, DATA-04).
    """
    by_ticker: dict[str, dict[str, float]] = {}
    for row in rows:
        closes = by_ticker.setdefault(row.ticker, {})
        if row.close is not None:
            closes[row.date] = row.close
    tickers = tuple(sorted(by_ticker))
    if not tickers or not all(by_ticker.values()):
        return Prices(dates=(), tickers=tickers, closes={t: () for t in tickers})
    start = max(min(closes) for closes in by_ticker.values())
    dates = tuple(sorted({d for closes in by_ticker.values() for d in closes if d >= start}))
    return Prices(
        dates=dates,
        tickers=tickers,
        closes={t: _fill(t, by_ticker[t], dates, max_gap) for t in tickers},
    )


def _fill(ticker: str, closes: dict[str, float], dates: tuple[str, ...], max_gap: int) -> tuple[float, ...]:
    """The ticker's close on each date, a missing one taking the previous close."""
    filled: list[float] = []
    missing = 0
    for date in dates:
        if date in closes:
            filled.append(closes[date])
            missing = 0
            continue
        missing += 1
        if missing > max_gap:
            raise GapError(f"{ticker} misses more than {max_gap} dates in a row before {date}")
        filled.append(filled[-1])
    return tuple(filled)

